-- 2026-10-w3 G2: 動画レビュー 2 回目の指摘で A73(影・ベランダ・外の空間)・C75(もう少し暗く)の情景を修正
-- 適用先: ローカル MySQL / Aurora(content_key で解決)

-- A73
UPDATE quiz_stock_items q JOIN batch_sets b ON b.id = q.set_id SET q.content_fields = CAST('{"hook": "質問の名人も困る問題だ", "hint": "相手の様子を考えてみろ!", "question": "どんな人に聞いても、「はい」と答えてもらうことが絶対にできない質問がある。どんな質問だ?", "answer": "「寝ていますか?」(寝ていたら答えられない)", "explanation": "起きている人は「いいえ」と答え、寝ている人はそもそも答えられない。だから「はい」は返ってこない。ほかにも答えはたくさんあるぞ。探してみろ!", "coach_comment": "質問の裏まで読んだな!", "tags": ["なぞなぞ", "朝の一問", "発想の転換"], "summary": "誰に聞いても「はい」と答えてもらえない質問を問う英語圏の定番なぞ。答えは「寝ていますか?」。起きていれば「いいえ」、寝ていれば答えられない。", "illustration_scene": "家の中のリビングの室内。左の壁の窓から朝日が差し込み、窓の外は青空だけ。部屋の中央、ソファの前の床に、マイクを持った人の後ろ姿が立っている。影はすべて窓の光と同じ向きに、自然な長さで床に落とす。マイクの横に大きな吹き出しと「?」。顔・「?」以外の文字は描かない。"}' AS JSON) WHERE b.set_code = 'logic-training-1' AND q.content_key = 'morning-069';

-- C75
UPDATE quiz_stock_items q JOIN batch_sets b ON b.id = q.set_id SET q.content_fields = CAST('{"hook": "冬の川辺のミステリーだ", "hint": "川のようすを想像してみろ!", "question": "深くて広い川の向こう岸にいる犬を呼んだ。橋も船もないのに、犬は一度もぬれずに、まっすぐこちらへ来れた。なぜ?", "answer": "川が凍っていて、氷の上を走ってきたから", "explanation": "泳ぎ方や渡り方を考えると行き詰まる。真冬の夜、川は一面凍っていた。犬は氷の上を走ってきたので、一度もぬれなかったのだ。", "coach_comment": "季節まで読み切ったな!", "tags": ["水平思考", "夜の一問", "ひっかけ"], "summary": "深く広い川の向こう岸の犬が、橋も船もないのにぬれずにまっすぐ来れた理由を問う英語圏の定番なぞ。答えは川が凍っていた。", "illustration_scene": "冬の夜、月明かりの川辺。手前の岸から見た深く広い川と、向こう岸にちょこんと座ってこちらを見る犬。川面は一面なめらかで、さざ波も揺らぎもない、夜の暗さになじむくすんだ紺灰色の平らな面。月明かりがぼんやり広がるだけで、川面に映り込みは描かない。空に星。川の上に大きな「?」。人物・「?」以外の文字は描かない。"}' AS JSON) WHERE b.set_code = 'logic-training-1' AND q.content_key = 'night-069';
